SELECT counts.breakdown_value AS `context.columns.breakdown_value`, tuple(counts.visitors, counts.previous_visitors) AS `context.columns.visitors`, tuple(counts.views, counts.previous_views) AS `context.columns.views`, tuple(bounce.bounce_rate, bounce.previous_bounce_rate) AS `context.columns.bounce_rate`, divide(`context.columns.visitors`.1, sum(`context.columns.visitors`.1) OVER ()) AS `context.columns.ui_fill_fraction` FROM (SELECT breakdown_value AS breakdown_value, uniqIf(filtered_person_id, and(greaterOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS visitors, uniqIf(filtered_person_id, 0) AS previous_visitors, sumIf(filtered_pageview_count, and(greaterOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS views, sumIf(filtered_pageview_count, 0) AS previous_views FROM (SELECT any(if(not(empty(events__override.distinct_id)), events__override.person_id, events.person_id)) AS filtered_person_id, count() AS filtered_pageview_count, nullIf(toString(events.properties.`$pathname`), '') AS breakdown_value, events__session.session_id AS session_id, min(events__session.`$start_timestamp`) AS start_timestamp FROM events_json AS events LEFT JOIN (SELECT toString(reinterpretAsUUID(bitOr(bitShiftLeft(raw_sessions.session_id_v7, 64), bitShiftRight(raw_sessions.session_id_v7, 64)))) AS session_id, min(toTimeZone(raw_sessions.min_timestamp, 'UTC')) AS `$start_timestamp`, raw_sessions.session_id_v7 AS session_id_v7 FROM raw_sessions WHERE and(equals(raw_sessions.team_id, TEAM_ID), greaterOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions.session_id_v7) AS events__session ON equals(toUInt128(toUUIDOrNull(events.properties.`$session_id`)), events__session.session_id_v7) LEFT OUTER JOIN (SELECT argMax(person_distinct_id_overrides.person_id, person_distinct_id_overrides.version) AS person_id, person_distinct_id_overrides.distinct_id AS distinct_id FROM person_distinct_id_overrides WHERE equals(person_distinct_id_overrides.team_id, TEAM_ID) GROUP BY person_distinct_id_overrides.distinct_id HAVING equals(argMax(person_distinct_id_overrides.is_deleted, person_distinct_id_overrides.version), 0) SETTINGS optimize_aggregation_in_order=1) AS events__override ON equals(events.distinct_id, events__override.distinct_id) WHERE and(equals(events.team_id, TEAM_ID), and(or(equals(events.event, '$pageview'), equals(events.event, '$screen')), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1, 1)) GROUP BY session_id, breakdown_value) GROUP BY breakdown_value) AS counts LEFT JOIN (SELECT breakdown_value AS breakdown_value, avgIf(is_bounce, and(greaterOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(start_timestamp, assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC'))))) AS bounce_rate, avgIf(is_bounce, 0) AS previous_bounce_rate FROM (SELECT events__session.`$entry_pathname` AS breakdown_value, any(events__session.`$is_bounce`) AS is_bounce, events__session.session_id AS session_id, min(events__session.`$start_timestamp`) AS start_timestamp FROM events_json AS events LEFT JOIN (SELECT path(nullIf(nullIf(argMinMerge(raw_sessions.entry_url), 'null'), '')) AS `$entry_pathname`, if(equals(uniqMerge(raw_sessions.pageview_uniq), 0), NULL, not(or(greater(uniqMerge(raw_sessions.pageview_uniq), 1), greater(uniqMerge(raw_sessions.autocapture_uniq), 0), greaterOrEquals(dateDiff('second', min(toTimeZone(raw_sessions.min_timestamp, 'UTC')), max(toTimeZone(raw_sessions.max_timestamp, 'UTC'))), 10)))) AS `$is_bounce`, toString(reinterpretAsUUID(bitOr(bitShiftLeft(raw_sessions.session_id_v7, 64), bitShiftRight(raw_sessions.session_id_v7, 64)))) AS session_id, min(toTimeZone(raw_sessions.min_timestamp, 'UTC')) AS `$start_timestamp`, raw_sessions.session_id_v7 AS session_id_v7 FROM raw_sessions WHERE and(equals(raw_sessions.team_id, TEAM_ID), greaterOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), minus(assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC')), toIntervalDay(3))), lessOrEquals(fromUnixTimestamp(intDiv(toUInt64(bitShiftRight(raw_sessions.session_id_v7, 80)), 1000)), plus(assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')), toIntervalDay(3)))) GROUP BY raw_sessions.session_id_v7) AS events__session ON equals(toUInt128(toUUIDOrNull(events.properties.`$session_id`)), events__session.session_id_v7) WHERE and(equals(events.team_id, TEAM_ID), and(or(equals(events.event, '$pageview'), equals(events.event, '$screen')), or(and(greaterOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_FROM 00:00:00', 'UTC'))), lessOrEquals(toTimeZone(events.timestamp, 'UTC'), assumeNotNull(toDateTime('DATE_TO 23:59:59', 'UTC')))), 0), 1, 1)) GROUP BY session_id, breakdown_value) GROUP BY breakdown_value) AS bounce ON equals(counts.breakdown_value, bounce.breakdown_value) WHERE isNotNull(counts.breakdown_value) ORDER BY `context.columns.visitors` DESC, `context.columns.views` DESC, `context.columns.breakdown_value` ASC LIMIT 100
